@push('scripts')<script>(function(){const list=document.getElementById('folder-list');if(!list)return;let dragged=null;list.querySelectorAll('.folder').forEach(card=>{card.addEventListener('dragstart',()=>{dragged=card;card.classList.add('dragging')});card.addEventListener('dragend',async()=>{card.classList.remove('dragging');const order=[...list.querySelectorAll('.folder')].map(x=>x.dataset.id);try{const r=await fetch('{{ route('admin.profile-builder.folders.reorder') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({order})});if(!r.ok)throw new Error()}catch(e){location.reload()}dragged=null});card.addEventListener('dragover',e=>{e.preventDefault();if(!dragged||dragged===card)return;const rect=card.getBoundingClientRect();if(e.clientY<rect.top+rect.height/2)card.before(dragged);else card.after(dragged)})})})();</script>@endpush
